import{z as E,x as b,o as e,c as m,q as s,j as n,D as i,d as t,s as r,S as p,b as l}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"logit bias","description":"","frontmatter":{"title":"logit bias","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/logit-bias.md","filePath":"llm/logit-bias.md","lastUpdated":1791063341000}'),A={name:"llm/logit-bias.md"};function d(B,a,g,c,T,_){const o=b("Mermaid");return e(),m("div",null,[a[2]||(a[2]=s('<h1 id="logit-bias" tabindex="-1">logit bias <a class="header-anchor" href="#logit-bias" aria-label="Permalink to &quot;logit bias&quot;">​</a></h1><div class="epigraph"><p>把若干 token 的分数加减一个常数，再送进 softmax：这是 API 能提供的最薄控制面，也是最容易和核采样、文法掩码打成一团的旋钮。</p><footer>—— 对照 OpenAI 兼容接口里的 logit_bias 字段，以及逐步约束如何改支撑集</footer></div><p><a href="/llm/ngram-blocking">上一课</a>把已出现 n-gram 做成硬零。本课把闸门放松：logit bias 对指定 token 加或减一个有限偏置，再进入温度与核。它出现在<a href="/llm/openai-compat-api">兼容 API</a> 里，是产品侧最常见的「不要说这个词」开关，也是把白名单做成软偏好的方式。后课才问温度如何改推理路径；本课先把 <em>逐步仿射变换</em> 钉死，避免和采样超参混成一个旋钮。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>硬阻断不能表达「尽量别出现、但语法需要时可以」。频率惩罚按出现次数线性减，对象是 <em>已经写过的</em> token；产品还想对 <em>尚未出现</em> 的词预置偏好：抬高某个选项字母、压低脏话表、把 EOS 提前。缺口是一套与 \\(\\pi\\) 相加的稀疏向量 \\(b\\in\\mathbb{R}^{|\\mathcal{V}|}\\)，使</p> \\[p(x_t)\\propto \\exp\\big((z_t+b)_{x_t}/T\\big). \\]<p>\\(b\\) 的索引在 token id 空间，不在 Unicode 空间。<span class="marginnote">术语翻译：「logit」是 softmax 之前那组没归一化的原始打分。给某个 token 的 logit 加常数 \\(b\\) 再过 softmax，效果等价于把它的概率先验乘上 \\(e^{b/T}\\) 倍——\\(b=+2\\)、\\(T=1\\) 时就是放大到约 7.4 倍，\\(b=-2\\) 时压到约 0.14 倍。它是「改打分」，不是「改规则」。</span>调用方若按字符串想「禁止 apple」，必须枚举所有 BPE 片；漏掉一个片，模型会改走 <code>Apple</code> 或 <code> apples</code>。这是 bias 作为 API 的主要陷阱，不是数学。</p><p><span class="marginnote">\\(b_i=+\\infty\\) 或实现里的极大值等于硬白名单；\\(b_i=-\\infty\\) 等于硬黑名单。有限 bias 与核的相互作用：被压低但仍在核里的 token 仍可能被抽中。文档必须写清是先加 bias 再核，还是先核再加——后者几乎无意义，因为核外已经是零。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>推荐顺序：文法掩码 → n-gram 阻断 → logit bias → 除以 \\(T\\) → top-\\(k\\) / top-\\(p\\) → 归一化采样。与<a href="/llm/sampling-temperature-topp">核采样课</a>同一协议，只是多了一层仿射。白名单应优先走文法（合法集精确），不要用很大的正 bias 冒充约束：softmax 仍给名单外非零质量，除非同时 mask。</p><p>服务端应把 \\(b\\) 做成稀疏对列表，而不是每次物化 \\(|\\mathcal{V}|\\) 向量。词表 10 万时，稠密 \\(b\\) 的搬运会接近一次无用的带宽税。<span class="marginnote">数字实例：10 万词表的稠密 bias 向量按 float32 存是 \\(10^5\\times4\\) 字节 \\(=400\\) KB；而一条请求通常只改几十个 token，稀疏对列表不过几百字节——差了三个数量级。批量服务里每个请求都带一份，省的就是这块。</span>多请求连续批时，每条请求的 \\(b\\) 不同，采样器内核必须按请求施加——这是后课采样器内核要接的形状。</p>',11)),(e(),n(p,null,{default:i(()=>[r(o,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20Z%5B%22logits%20z%22%5D%20--%3E%20G%5B%22%E6%96%87%E6%B3%95%20%2F%20n-gram%20%E6%8E%A9%E7%A0%81%22%5D%0A%20%20G%20--%3E%20B%5B%22%E5%8A%A0%E4%B8%8A%E7%A8%80%E7%96%8F%20logit%20bias%22%5D%0A%20%20B%20--%3E%20T%5B%22%E9%99%A4%E4%BB%A5%E6%B8%A9%E5%BA%A6%20T%22%5D%0A%20%20T%20--%3E%20P%5B%22top-k%20%2F%20top-p%22%5D%0A%20%20P%20--%3E%20S%5B%22%E9%87%87%E6%A0%B7%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l("h2",{id:"机制",tabindex:"-1"},[t("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=l("p",null,"对 softmax，加 \\(b_i\\) 等价于把先验乘上 \\(\\exp(b_i/T)\\)。\\(T\\) 越小，同一 \\(b\\) 越「硬」：低温下 \\(b=-2\\) 已经接近禁令，高温下只是略降。同一个偏置在不同温度下的实际强度：",-1)),(e(),n(p,null,{default:i(()=>[r(o,{id:"mermaid-36",class:"mermaid",graph:"flowchart%20TD%0A%20%20B%5B%22%E5%90%8C%E4%B8%80%E4%B8%AA%20bias%20b%20%3D%20-2%22%5D%20--%3E%20T1%5B%22T%3D0.3%3A%20%E5%85%88%E9%AA%8C%E4%B9%98%20e%5E-6.7%20%E2%89%88%200.001%22%5D%0A%20%20B%20--%3E%20T2%5B%22T%3D1.0%3A%20%E5%85%88%E9%AA%8C%E4%B9%98%20e%5E-2%20%E2%89%88%200.14%22%5D%0A%20%20B%20--%3E%20T3%5B%22T%3D1.5%3A%20%E5%85%88%E9%AA%8C%E4%B9%98%20e%5E-1.3%20%E2%89%88%200.26%22%5D%0A%20%20T1%20--%3E%20R1%5B%22%E2%89%88%20%E7%A6%81%E4%BB%A4%2C%20%E4%BA%8B%E5%AE%9E%E5%A4%B1%E6%95%88%22%5D%0A%20%20T2%20--%3E%20R2%5B%22%E6%98%8E%E6%98%BE%E5%8E%8B%E5%88%B6%E4%BD%86%E4%BB%8D%E5%8F%AF%E8%83%BD%E6%8A%BD%E4%B8%AD%22%5D%0A%20%20T3%20--%3E%20R3%5B%22%E5%8F%AA%E6%98%AF%E7%95%A5%E5%BE%AE%E9%99%8D%E6%B8%A9%22%5D%0A"})]),fallback:i(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=s('<p>因此 bias 与温度不可独立宣传：「禁止脏话、同时 \\(T=1.2\\)」会把黑名单重新变软。<span class="marginnote">直觉类比：bias 是一根压杆，温度是杠杆的支点位置。同一根杆，低温（分布尖）时轻轻一压就把词彻底压扁；高温（分布平）时压了半天词还站着。所以「我设了黑名单」这句话，必须连温度一起说才算数。</span>EOS bias 常被用来控长度：正 bias 提前结束，负 bias 拖长。这与长度惩罚不同——后者重排已生成假设，前者改下一步停不停。</p><p><span class="marginnote">不要用 bias 实现 JSON schema。嵌套与状态机转移不是一张静态表能表达的。静态表只适合与前缀无关的全局偏好。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>跨模型词表不同，同一字符串的 id 列表不可移植；兼容层若只转发整数 id，换模型即静默失效。投机解码时 bias 必须进入 \\(p\\) 与 \\(q\\) 两侧，否则<a href="/llm/speculative-decoding">无损接受</a>对的是未偏置的目标。评测与线上必须同一张 \\(b\\)：安全词表若只在网关注入、评测脚本没加，数字会骗人。</p><p>出处以 API 契约与约束解码文献为准，没有单独的「logit bias 论文」。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>logit bias 是逐步仿射，硬 \\(\\pm\\infty\\) 才等于掩码。</li><li>作用在 token id；字符串到片的枚举必须完整。</li><li>顺序：掩码 → bias → 温度 → 核；与 \\(T\\) 耦合。</li><li>静态 bias 替代不了文法；连续批里 \\(b\\) 是每请求状态。</li><li>投机两侧都要加同一 \\(b\\)。</li><li>后课把 \\(T\\) 从「文风」接到「推理对不对」。</li><li>出处：OpenAI 兼容 API 的 <code>logit_bias</code>；逐步掩码见约束解码文献。</li></ul>',7))])}const D=E(A,[["render",d]]);export{h as __pageData,D as default};
